export const DEFAULT_BASE_BOUNCE_LIMIT=3;export function normalizeBaseBounceLimit(e,t=3){const n=Number(e);return Number.isFinite(n)?Math.max(1,Math.min(100,Math.floor(n))):t}export function neutralPlatform(e,t){return{...e,type:"neutral",receptions:0,bounceLimit:normalizeBaseBounceLimit(t)}}export function receivePlatform(e){return e.type!=="neutral"?!1:(e.receptions=(e.receptions||0)+1,e.receptions>=e.bounceLimit)}export function awardPlatformCombo(e){return e.comboAwarded?!1:(e.comboAwarded=!0,!0)}export function platformOpacity(e){return e.type!=="neutral"||!e.bounceLimit?1:Math.max(.2,1-(e.receptions||0)/e.bounceLimit*.8)}export function shouldSpawnLivePlatform(e){return e>0}export function shouldSpawnNotableBuyPlatform(e,t){return Number(e)>Number(t)}export function notableBuyPlatformStats(e,t=1){const n=Math.max(1,Math.min(4,Number(e)||1));return{width:t*Math.min(220,95+n*30),bounce:Math.min(2.4,1.05+n*.22)}}
